import{_ as t,o as r,c as o,a2 as n}from"./chunks/framework.BefGvJmu.js";const u=JSON.parse('{"title":"PAI Terminology","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"spec/terminology.md","filePath":"spec/terminology.md"}'),a={name:"spec/terminology.md"};function i(d,e,s,c,l,p){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="pai-terminology" tabindex="-1">PAI Terminology <a class="header-anchor" href="#pai-terminology" aria-label="Permalink to &quot;PAI Terminology&quot;">​</a></h1><p>2026-11-09 · Informative vocabulary for the content protocol and file format.</p><h2 id="participants" tabindex="-1">Participants <a class="header-anchor" href="#participants" aria-label="Permalink to &quot;Participants&quot;">​</a></h2><p><strong>PAI client</strong>: a program that sends PAI requests and processes responses. It can be part of a personal AI application, a command-line tool, or a web backend.</p><p><strong>PAI server</strong>: a program that implements PAI endpoints. The content profile defines discovery, publication, updates, retrieval, and file downloads. A server can consist of one process or several components. Client and server describe communication roles, following the terminology of <a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-3.3" target="_blank" rel="noreferrer">HTTP, RFC 9110 §3.3</a>.</p><p><strong>Service provider</strong>: the organization or person operating a PAI service. Use “server” for protocol behavior and “service provider” for deployment, accounts, operations, and commercial integration. Follo or an individual operator can run a PAI server.</p><p><strong>Host application</strong>: the user-facing application or runtime containing a PAI client. “Harness” describes an agent execution and tool-orchestration environment in implementation documentation. Protocol requirements apply to the client that sends the requests.</p><p><strong>Agent</strong>: an AI system that performs tasks and calls tools for a user. A personal agent can access a PAI service through a client. A <strong>hosted agent</strong> is an agent operated by a service to respond within a user&#39;s authorized scope. Hosted-agent authorization and interaction rules are planned extensions.</p><h2 id="publication-identity" tabindex="-1">Publication identity <a class="header-anchor" href="#publication-identity" aria-label="Permalink to &quot;Publication identity&quot;">​</a></h2><p><strong>Publisher</strong>: the principal identified by the server from a credential and authorized to manage the resulting published resources. The server returns this identity in <code>publisherId</code>.</p><p><strong>Author</strong>: the creator or credited author of the content. Authorship can be expressed in document content or associated metadata. An author name in a file does not grant publication permissions.</p><p>Publisher identifiers are local to a service. Credential issuance is managed by the service provider. The content profile uses Bearer credentials for authenticated writes; <a href="/pai-website/spec/service.html">SERVICE.md</a> defines authentication and ownership checks.</p><h2 id="content-and-versioning" tabindex="-1">Content and versioning <a class="header-anchor" href="#content-and-versioning" aria-label="Permalink to &quot;Content and versioning&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th><th>Wire or file field</th></tr></thead><tbody><tr><td>Document</td><td>The content object containing text, layout, images, and metadata</td><td>The complete document object; <code>document</code> in ZIP packaging</td></tr><tr><td>Document revision</td><td>A document&#39;s edit counter; preserved during packaging-only conversion</td><td><code>document.revision</code></td></tr><tr><td>Published resource</td><td>An addressable server record for a publisher&#39;s document</td><td><code>resource</code>, <code>resource.id</code></td></tr><tr><td>Publication version</td><td>A stored version of a published resource</td><td><code>resource.version</code></td></tr><tr><td>Snapshot</td><td>The fixed content and metadata stored for a publication version</td><td>The resource returned by <code>versionUrl</code></td></tr><tr><td>Content block</td><td>Content with a stable ID that can be arranged and moved together</td><td>Document <code>regions[]</code>; structured-content <code>blocks[]</code> uses the same IDs</td></tr><tr><td>Layout row</td><td>Ordered placement and relative widths for one to three blocks</td><td><code>sections[]</code></td></tr><tr><td>Image asset</td><td>Original image bytes and associated metadata</td><td><code>assets</code></td></tr><tr><td>Structured content</td><td>JSON containing document metadata, blocks in reading order, asset metadata, and source URLs</td><td>The response at <code>representations.content</code></td></tr><tr><td>Content hash</td><td>The digest calculated from document fields and original image bytes, including document ID and revision</td><td><code>contentHash</code>, <code>contentHashAlgorithm</code></td></tr><tr><td>File packaging</td><td>The storage of the same document in ZIP or HTML</td><td><code>.pai</code>, <code>.pai.html</code></td></tr></tbody></table><p>The term “resource” denotes an addressable object, and “representation” denotes its transferred form, consistent with <a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-3.1" target="_blank" rel="noreferrer">RFC 9110 §3.1–3.2</a>. A PAI content hash supports comparison and retry handling; it is not a publisher credential or a digital signature.</p><h2 id="interface-terms" tabindex="-1">Interface terms <a class="header-anchor" href="#interface-terms" aria-label="Permalink to &quot;Interface terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Service discovery</td><td>Reading the service descriptor to obtain protocol version, capabilities, authentication scheme, and endpoint URLs</td></tr><tr><td>Endpoint</td><td>A URL that accepts a defined class of requests</td></tr><tr><td>Capability</td><td>An implemented operation advertised in <code>capabilities</code></td></tr><tr><td>Content profile</td><td>The publication and retrieval rules selected by <code>profile: &quot;content&quot;</code></td></tr><tr><td>Authentication</td><td>Establishing the identity associated with a credential</td></tr><tr><td>Authorization</td><td>Determining whether that identity may perform an operation</td></tr><tr><td>Source URL</td><td>A URL for a block in a specific publication version, carried in <code>sourceUrl</code></td></tr></tbody></table><p>Normative requirements use the uppercase BCP 14 terms defined in the <a href="/pai-website/spec/#conformance-language">specification overview</a>. Field names retain their exact spelling across specifications, guides, and implementations.</p>',18)])])}const m=t(a,[["render",i]]);export{u as __pageData,m as default};
